using Xunit;\nusing Moq;\nusing MyProject.Services;\nusing MyProject.Controllers;\nusing MyProject.Models;\nusing System.Threading.Tasks;\nusing Microsoft.AspNetCore.Mvc;\nusing System.Collections.Generic;\n\nnamespace MyProject.Tests\n{\n public class AccountsControllerTests\n {\n [Fact]\n public async Task GetAccounts_Pagination_ReturnsPagedResult()\n {\n // Arrange\n var mockService = new Mock<ISalesforceService>();\n var items = new List<AccountDto>\n {\n new AccountDto{ Id = "1", Name = "A" },\n new AccountDto{ Id = "2", Name = "B" }\n };\n\n var paged = new PagedResult<AccountDto>\n {\n Items = items,\n PageNumber = 2,\n PageSize = 2,\n TotalCount = 6\n };\n\n mockService.Setup(s => s.GetAccountsAsync(2, 2)).ReturnsAsync(paged);\n\n var controller = new AccountsController(mockService.Object);\n\n // Act\n var actionResult = await controller.GetAccounts(2, 2);\n\n // Assert\n var ok = Assert.IsType<OkObjectResult>(actionResult);\n var returned = Assert.IsType<PagedResult<AccountDto>>(ok.Value);\n Assert.Equal(2, returned.PageNumber);\n Assert.Equal(2, returned.PageSize);\n Assert.Equal(6, returned.TotalCount);\n Assert.Equal(2, returned.Items.Count);\n }\n }\n}